CREATE TEMPORARY VIEW order_nmv_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,SPLIT(feature_detail, '-')[0] AS page_type
    ,IF(SIZE(SPLIT(feature_detail, '-')) = 3,  SPLIT(feature_detail, '-')[1], NULL)  AS page_section
    ,IF(SIZE(SPLIT(feature_detail, '-')) = 3,  SPLIT(feature_detail, '-')[2], SPLIT(feature_detail, '-')[1])  AS card_type
    ,IF(search_entrance IS NOT NULL AND TRIM(LOWER(search_entrance)) != '', TRIM(LOWER(search_entrance)), 'NA') AS search_entrance
    ,IF(search_mid IS NOT NULL AND TRIM(LOWER(search_mid)) != '', search_mid, 'NA') AS search_mid
    ,IF(is_ads IS NOT NULL, CAST(is_ads AS STRING), 'false') AS is_ads
    ,IF(sort_type IS NOT NULL, sort_type, 'NULL') AS sort_type
    ,IF(COALESCE(keyword, '') = '', 'false', 'true') AS with_keyword
    ,net_order_cnt
    ,nmv
    ,local_date
FROM
    srdi_mart.dwd_sr_data_warehouse_platform_nmv
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date}
    AND user_id > 0
    AND reporting_business_line = 'Search'
    AND reporting_module = 'Global Search'
UNION ALL
