    ,IF(source1_is_ads IS NOT NULL, CAST(source1_is_ads AS STRING), 'false') AS is_ads
    ,IF(source1_sort_type IS NOT NULL, source1_sort_type, 'NULL') AS sort_type
    ,IF(COALESCE(source1_keyword, '') = '', 'false', 'true') AS with_keyword
    ,net_order_cnt
