    ,IF(SIZE(SPLIT(source2_feature_detail, '-')) = 3,  SPLIT(source2_feature_detail, '-')[1], NULL)  AS page_section
    ,IF(SIZE(SPLIT(source2_feature_detail, '-')) = 3,  SPLIT(source2_feature_detail, '-')[2], SPLIT(source2_feature_detail, '-')[1])  AS card_type
    ,IF(source2_search_entrance IS NOT NULL AND TRIM(LOWER(source2_search_entrance)) != '', TRIM(LOWER(source2_search_entrance)), 'NA') AS search_entrance
    ,IF(source2_search_mid IS NOT NULL AND TRIM(LOWER(source2_search_mid)) != '', source2_search_mid, 'NA') AS search_mid
