CREATE TEMPORARY VIEW dwm_order_nmv_${grass_region_without_quote} AS
SELECT
    user_id
    ,ARRAY(search_entrance, '__ALL__') AS search_entrances
    ,ARRAY(is_ads, '__ALL__') AS is_adss
    ,IF(page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND page_section IS NULL AND card_type IN ('item', 'video', 'livestream')
        , ARRAY(concat_ws('-',page_section,card_type), '__ALL__', 'item+video+live'), ARRAY(concat_ws('-',page_section,card_type), '__ALL__')) AS card_types
    ,ARRAY(sort_type, '__ALL__') AS sort_types
    ,local_date
    ,IF(search_mid LIKE 'image%', array(search_mid, '__ALL__', 'mutimodel_search_all'), array(search_mid, '__ALL__', 'text_search_all')) AS search_mids
    ,ARRAY(with_keyword, '__ALL__') AS with_keywords
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv
FROM
    order_nmv_raw_${grass_region_without_quote}
GROUP BY 
    user_id
    ,search_entrance
    ,is_ads
    ,page_type
    ,page_section
    ,card_type
    ,sort_type
    ,local_date
    ,search_mid
    ,with_keyword;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_order_nmv_explode_${grass_region_without_quote} AS
SELECT
    user_id
    ,search_entrance
    ,is_ads
    ,card_type
    ,sort_type
    ,local_date
    ,'__ALL__' AS search_mid
    ,'__ALL__' AS with_keyword
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv_usd
FROM
    dwm_order_nmv_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(search_entrances) AS search_entrance
    LATERAL VIEW EXPLODE(is_adss) AS is_ads
    LATERAL VIEW EXPLODE(card_types) AS card_type
    LATERAL VIEW EXPLODE(sort_types) AS sort_type
GROUP BY 
    1,2,3,4,5,6
UNION ALL 
SELECT
    user_id
    ,'__ALL__' AS search_entrance
    ,'__ALL__' AS is_ads
    ,'__ALL__' AS card_type
    ,'__ALL__' AS sort_type
    ,local_date
    ,search_mid
    ,with_keyword
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv_usd
FROM
    dwm_order_nmv_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(search_mids) AS search_mid
    LATERAL VIEW EXPLODE(with_keywords) AS with_keyword
WHERE
    search_mid != '__ALL__'
    OR with_keyword != '__ALL__'
GROUP BY 
    1,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_nmv_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,a.local_date AS local_date
    ,search_entrance
    ,is_ads
    ,card_type
    ,sort_type
    ,search_mid
    ,with_keyword
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv_usd) AS nmv_usd
    ,COUNT(DISTINCT IF(net_order_cnt > 0, a.user_id, NULL)) AS net_order_uu
FROM
    dwm_order_nmv_explode_${grass_region_without_quote} a
JOIN
    user_exp_mapping_7d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY
    1,2,3,4,5,6,7,8;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_order_nmv_platform_${grass_region_without_quote} AS
SELECT
    user_id
    ,local_date
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv_usd
FROM
