    AND local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date}
    AND user_id > 0
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_nmv_platform_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,a.local_date AS local_date
    ,SUM(net_order_cnt) AS platform_net_order_cnt
    ,SUM(nmv_usd) AS platform_nmv
    ,COUNT(DISTINCT IF(net_order_cnt > 0, a.user_id, NULL)) AS platform_net_order_uu
FROM
    dwm_order_nmv_platform_${grass_region_without_quote} a
JOIN
    user_exp_mapping_7d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY
    exp_group_id
    ,a.local_date;

